#include <vector>
#include <numeric>
#include <cmath>
using namespace std;

class Solution {
public:
    int minElements(vector<int>& nums, int limit, int goal) {
        long long total = 0;
        for (int x : nums) total += x;
        long long diff = abs((long long)goal - total);
        return (diff + limit - 1) / limit;
    }
};

class Solution {
    public int minElements(int[] nums, int limit, int goal) {
        long total = 0;
        for (int x : nums) total += x;
        long diff = Math.abs((long)goal - total);
        return (int)((diff + limit - 1) / limit);
    }
}

/**
 * @param {number[]} nums
 * @param {number} limit
 * @param {number} goal
 * @return {number}
 */
var minElements = function(nums, limit, goal) {
    let total = 0;
    for (const x of nums) total += x;
    const diff = Math.abs(goal - total);
    return Math.floor((diff + limit - 1) / limit);
};
